"""
Execution-grounded verification of agent-authored workspaces.

Five gates, each of which either runs the code or performs AST analysis on it:

    syntax     Every authored .py file must parse (`ast.parse`). Empty
               workspaces (0 Python files) return `FAILED`.
    build      Packaging metadata (`pyproject.toml`, `setup.py`, or `setup.cfg`)
               must exist and be valid/installable. When `pyproject.toml` is
               present, validate it with `tomllib` (must parse as valid TOML and
               contain at least one of `[project]`, `[build-system]`, or
               `[tool]` tables; an empty or malformed `pyproject.toml` returns
               `FAILED`), and run `pip install -e . --no-deps --no-build-isolation`
               when `pip` is available.
    smoke      Non-test authored modules must import in a subprocess with both
               `workdir` and `os.path.join(workdir, "src")` on `PYTHONPATH`. If
               no importable modules exist or any module fails with a syntax or
               runtime error, return `FAILED`. If module imports fail solely
               with `ModuleNotFoundError` for uninstalled third-party packages
               (e.g. `opentelemetry`), return `SKIPPED` (not `FAILED`).
    tests      Discover test files (`"test" in os.path.basename(p).lower()`;
               if none exist, return `FAILED`) and run them with both `workdir`
               and `os.path.join(workdir, "src")` on `PYTHONPATH`. Use `pytest`
               if installed in `self.python`; otherwise run a stdlib fallback
               subprocess that imports each test file and collects/executes BOTH
               bare `def test_*()` functions (taking 0 required args) AND
               `unittest.TestCase` subclasses (because `unittest discover`
               ignores bare `def test_*()` functions). If 0 tests are collected
               because of `ModuleNotFoundError` for an uninstalled third-party
               package, return `SKIPPED`.
    telemetry  AST analysis of authored `.py` files must find BOTH (1) an actual
               `import opentelemetry` or `from opentelemetry ... import ...` node AND (2) at least one AST `Call` to a tracer/span method or
               function (`start_as_current_span`, `start_span`, `get_tracer`,
               `get_tracer_provider`, `set_tracer_provider`, `get_meter`). A
               comment/docstring mention or a bare `import opentelemetry`
               without any tracer/span call must return `FAILED`.

Each result carries the `method` used to reach it. A gate that could not be
evaluated returns `SKIPPED` rather than `PASSED`, so a missing tool can never be
mistaken for a success, and `SKIPPED` gates are excluded from the fitness
denominator (`evaluated_gates` and `score_penalty`) rather than scored as
failures (`score_penalty = failed_gate_count * penalty_per_gate`).

The V1 verifier this replaces executed nothing in three of its four gates:
`build` was a filename substring match, `smoke` was `len(files) >= 3`, and
`telemetry` searched text that included the CEO's markdown prose, so an essay
mentioning OpenTelemetry passed. Six generations were selected on those
signals. The whole design rule here is that no gate may be satisfiable by
writing about it.

Usage:
    from hae.evaluation.harness import ExecutionHarness

    harness = ExecutionHarness()
    report = harness.verify_workspace(workspace, deliverable_text)
    print(report.summary(), report.gate_status)
"""

import ast
import os
import re
import subprocess
import sys
import tempfile
import time
import traceback
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Try to import tomllib (Python 3.11+) or tomli (backport)
try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

# Import artifacts for filtering
try:
    from hae.evaluation.artifacts import filter_bundle
except ImportError:
    # Fallback if artifacts.py is not in path or fails to import
    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        # Minimal fallback: return bundle as-is if filtering logic is unavailable
        # In a real scenario, this should mirror the logic in artifacts.py
        return bundle


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        ev = self.evaluated_gates
        if not ev:
            return 0.0
        return len(self.passed_gates) / len(ev)

    def summary(self) -> str:
        passed = len(self.passed_gates)
        evaluated = len(self.evaluated_gates)
        return f"{passed}/{evaluated} gates passed. Penalty: {self.score_penalty:.2f}"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename
    # Pattern: ```[language] [filename]\n...\n```
    # We look for lines that look like filenames in the fence header
    pattern = r"```(?:\w+)?\s*(?:([^\n]+))?\n(.*?)\n```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for filename, content in matches:
        if not filename:
            continue
        # Clean up filename: remove backticks if present, strip whitespace
        clean_name = filename.strip().strip('`').strip()
        if not clean_name:
            continue
        # Basic validation: must look like a file path
        if '/' in clean_name or '.' in clean_name:
            bundle[clean_name] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            try:
                if hasattr(workspace, 'export_bundle'):
                    raw_bundle = workspace.export_bundle()
                    bundle = filter_bundle(raw_bundle)
                    source = 'workspace'
                elif hasattr(workspace, 'files'):
                    # Assume dict-like
                    bundle = filter_bundle(workspace.files)
                    source = 'workspace'
            except Exception:
                pass

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        with tempfile.TemporaryDirectory() as tmpdir:
            for path, content in bundle.items():
                # Normalize path separators to ensure consistent handling
                clean_path = path.replace('**', '').strip()
                if not clean_path:
                    continue
                full_path = os.path.join(tmpdir, clean_path)
                # Ensure directory exists
                dir_path = os.path.dirname(full_path)
                if dir_path:
                    os.makedirs(dir_path, exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)
            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        start_time = time.time()

        # Determine authored files strictly from the provided map if available,
        # filtering out generated/malformed paths using the canonical artifacts logic.
        if authored is not None:
            filtered_bundle = filter_bundle(authored)
            authored_files = [f for f in filtered_bundle.keys() if os.path.exists(os.path.join(workdir, f))]
        else:
            # Fallback: discover files on disk and filter them
            all_files = []
            for root, dirs, files in os.walk(workdir):
                dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('__pycache__', 'venv', '.venv')]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    all_files.append(rel_path)

            bundle = {}
            for f in all_files:
                try:
                    with open(os.path.join(workdir, f), 'r', encoding='utf-8') as fh:
                        bundle[f] = fh.read()
                except Exception:
                    pass
            filtered_bundle = filter_bundle(bundle)
            authored_files = list(filtered_bundle.keys())

        python_files = [f for f in authored_files if f.endswith('.py')]

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, python_files))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored_files))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, python_files))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, python_files))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=len(authored_files),
            python_files=len(python_files),
            source=source,
            harness_version='3.0-execution'
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if len(python_files) == 0:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found.',
                duration_s=time.time() - start,
                evidence={'files': []}
            )

        errors = []
        for f in python_files:
            full_path = os.path.join(workdir, f)
            try:
                with open(full_path, 'r', encoding='utf-8') as fh:
                    content = fh.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{f}: {e}")
            except Exception as e:
                errors.append(f"{f}: {e}")

        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='Syntax errors found: ' + '; '.join(errors),
                duration_s=time.time() - start,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail='All Python files parsed successfully.',
            duration_s=time.time() - start,
            evidence={'files': python_files}
        )

    def _gate_build(self, workdir: str, authored_files: List[str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored_files
        has_setup_py = 'setup.py' in authored_files
        has_setup_cfg = 'setup.cfg' in authored_files

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='filesystem_check',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found.',
                duration_s=time.time() - start,
                evidence={'files': authored_files}
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            if tomllib is None:
                return GateResult(
                    name='build',
                    status=SKIPPED,
                    method='tomllib_check',
                    detail='tomllib not available to validate pyproject.toml.',
                    duration_s=time.time() - start,
                    evidence={}
                )

            pyproject_path = os.path.join(workdir, 'pyproject.toml')
            try:
                with open(pyproject_path, 'rb') as f:
                    data = tomllib.load(f)

                # Must contain at least one of these tables
                if not any(k in data for k in ('project', 'build-system', 'tool')):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib_check',
                        detail='pyproject.toml is missing required tables ([project], [build-system], or [tool]).',
                        duration_s=time.time() - start,
                        evidence={'keys': list(data.keys())}
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib_check',
                    detail=f'pyproject.toml is malformed: {e}',
                    duration_s=time.time() - start,
                    evidence={'error': str(e)}
                )

        # Attempt pip install if pip is available
        # We check for pip availability by trying to run it
        try:
            # Use a subprocess to check pip version to ensure it exists
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                check=True,
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available to verify installation.',
                duration_s=time.time() - start,
                evidence={}
            )

        # Run pip install -e .
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            if result.returncode != 0:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=time.time() - start,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out.',
                duration_s=time.time() - start,
                evidence={}
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start,
                evidence={'error': str(e)}
            )

        return GateResult(
            name='build',
            status=PASSED,
            method='pip_install',
            detail='Package installed successfully.',
            duration_s=time.time() - start,
            evidence={}
        )

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Exclude files that look like tests
        non_test_modules = []
        for f in python_files:
            basename = os.path.basename(f).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar
            # We need to handle src/ prefix if present
            rel_path = f
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            if rel_path.endswith('.py'):
                module_name = rel_path[:-3].replace('/', '.').replace('\\', '.')
                if module_name:
                    non_test_modules.append(module_name)

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No non-test Python modules found to import.',
                duration_s=time.time() - start,
                evidence={'files': python_files}
            )

        # Prepare environment
        env = os.environ.copy()
        # Add workdir and workdir/src to PYTHONPATH
        paths = [workdir, os.path.join(workdir, 'src')]
        existing_path = env.get('PYTHONPATH', '')
        if existing_path:
            paths.append(existing_path)
        env['PYTHONPATH'] = os.pathsep.join(paths)

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for module_name in non_test_modules:
            try:
                # Run a subprocess to import the module
                # We use -c to import and exit
                cmd = [self.python_executable, '-c', f'import {module_name}']
                result = subprocess.run(
                    cmd,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package or our own module
                        # If it's our own module failing to import due to missing deps, it's a fail.
                        # If it's a third-party dep, it's a skip.
                        # Heuristic: if the module name itself is not found, it's a fail.
                        # If a dependency inside is not found, it's a skip.
                        # This is tricky. Let's assume if the top-level module fails, it's a fail.
                        # If it fails inside, we might see the traceback.
                        # For simplicity, if ModuleNotFoundError is raised, we check if the module name is in the error.
                        if module_name in stderr:
                            import_errors.append(f"{module_name}: {stderr}")
                        else:
                            module_not_found_errors.append(f"{module_name}: {stderr}")
                    else:
                        import_errors.append(f"{module_name}: {stderr}")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import errors: ' + '; '.join(import_errors),
                duration_s=time.time() - start,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Imports skipped due to missing third-party dependencies: ' + '; '.join(module_not_found_errors),
                duration_s=time.time() - start,
                evidence={'skipped': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail='All non-test modules imported successfully.',
            duration_s=time.time() - start,
            evidence={'modules': non_test_modules}
        )

    def _gate_tests(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = [f for f in python_files if 'test' in os.path.basename(f).lower()]

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found.',
                duration_s=time.time() - start,
                evidence={'files': python_files}
            )

        # Prepare environment
        env = os.environ.copy()
        paths = [workdir, os.path.join(workdir, 'src')]
        existing_path = env.get('PYTHONPATH', '')
        if existing_path:
            paths.append(existing_path)
        env['PYTHONPATH'] = os.pathsep.join(paths)

        # Check if pytest is available
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                check=True,
                capture_output=True,
                timeout=10
            )
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    # Check if it's a collection error due to missing deps
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail='Tests skipped due to missing dependencies.',
                            duration_s=time.time() - start,
                            evidence={'stderr': result.stderr, 'stdout': result.stdout}
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail='Tests failed.',
                        duration_s=time.time() - start,
                        evidence={'stderr': result.stderr, 'stdout': result.stdout}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out.',
                    duration_s=time.time() - start,
                    evidence={}
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Pytest execution error: {e}',
                    duration_s=time.time() - start,
                    evidence={'error': str(e)}
                )
        else:
            # Fallback: stdlib unittest with custom runner to catch bare test_* functions
            all_passed = True
            errors = []
            skipped_deps = False

            runner_script = '''
import sys
import unittest
import importlib
import inspect

def run_tests(module_names):
    suite = unittest.TestSuite()
    for mod_name in module_names:
        try:
            mod = importlib.import_module(mod_name)
        except ModuleNotFoundError as e:
            print(f'MODULE_NOT_FOUND:{mod_name}:{e}', file=sys.stderr)
            sys.exit(2)
        except Exception as e:
            print(f'IMPORT_ERROR:{mod_name}:{e}', file=sys.stderr)
            sys.exit(1)

        # Collect TestCase subclasses
        for name, obj in inspect.getmembers(mod, inspect.isclass):
            if issubclass(obj, unittest.TestCase) and obj.__module__ == mod_name:
                suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(obj))

        # Collect bare test_* functions
        for name, obj in inspect.getmembers(mod, inspect.isfunction):
            if name.startswith('test_') and obj.__module__ == mod_name:
                # Wrap in a TestCase to run it
                class DynamicTest(unittest.TestCase):
                    def test_wrapper(self):
                        obj()
                DynamicTest.__name__ = f'Test_{name}'
                suite.addTest(DynamicTest('test_wrapper'))

    if suite.countTestCases() == 0:
        print('NO_TESTS_COLLECTED', file=sys.stderr)
        sys.exit(0)

    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)
    sys.exit(0 if result.wasSuccessful() else 1)

if __name__ == '__main__':
    run_tests(sys.argv[1:])
'''

            runner_path = os.path.join(workdir, '_fallback_runner.py')
            with open(runner_path, 'w') as f:
                f.write(runner_script)

            module_names = []
            for test_file in test_files:
                rel_path = test_file
                if rel_path.startswith('src/'):
                    rel_path = rel_path[4:]
                module_name = rel_path[:-3].replace('/', '.').replace('\\\\', '.')
                module_names.append(module_name)

            try:
                cmd = [self.python_executable, runner_path] + module_names
                result = subprocess.run(
                    cmd,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=30
                )
                if result.returncode == 2:
                    skipped_deps = True
                elif result.returncode != 0:
                    all_passed = False
                    errors.append(f'Test execution failed: {result.stderr}')
            except Exception as e:
                all_passed = False
                errors.append(f'Runner error: {e}')

            # Cleanup runner script
            try:
                os.remove(runner_path)
            except Exception:
                pass

            if not all_passed:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='unittest',
                    detail='Tests failed: ' + '; '.join(errors),
                    duration_s=time.time() - start,
                    evidence={'errors': errors}
                )

            if skipped_deps:
                return GateResult(
                    name='tests',
                    status=SKIPPED,
                    method='unittest',
                    detail='Tests skipped due to missing dependencies.',
                    duration_s=time.time() - start,
                    evidence={}
                )

        return GateResult(
            name='tests',
            status=PASSED,
            method='pytest' if has_pytest else 'unittest',
            detail='All tests passed.',
            duration_s=time.time() - start,
            evidence={'test_files': test_files}
        )

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        if not python_files:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No Python files to analyze.',
                duration_s=time.time() - start,
                evidence={}
            )

        has_import = False
        has_call = False
        errors = []

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for f in python_files:
            full_path = os.path.join(workdir, f)
            try:
                with open(full_path, 'r', encoding='utf-8') as fh:
                    content = fh.read()
                tree = ast.parse(content)

                for node in ast.walk(tree):
                    # Check for imports
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle method calls like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception as e:
                errors.append(f"{f}: {e}")

        if errors:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='AST analysis errors: ' + '; '.join(errors),
                duration_s=time.time() - start,
                evidence={'errors': errors}
            )

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry imports found.',
                duration_s=time.time() - start,
                evidence={'has_import': has_import, 'has_call': has_call}
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='OpenTelemetry imported but no tracer/span calls found.',
                duration_s=time.time() - start,
                evidence={'has_import': has_import, 'has_call': has_call}
            )

        return GateResult(
            name='telemetry',
            status=PASSED,
            method='ast_analysis',
            detail='OpenTelemetry instrumentation detected.',
            duration_s=time.time() - start,
            evidence={'has_import': has_import, 'has_call': has_call}
        )

